do $$begin if not public.is_valid_score_sheet_programme_snapshot((select p from pp where n='valid')) or not public.is_valid_score_sheet_programme_snapshot((select p from pp where n='sporttrap')) or not public.is_complete_score_sheet_programme_snapshot((select p from pp where n='legacy')) then raise exception 'valid/legacy rejected';end if;if public.is_valid_score_sheet_programme_snapshot('[]') or public.is_valid_score_sheet_programme_snapshot('{"schemaVersion":1,"snapshotId":"x","name":"x","family":"custom","source":"custom","sourceOrganisation":null,"sourceVersion":null,"templateId":null,"modified":false,"machineVocabulary":["A"],"areas":[]}') or public.is_valid_score_sheet_programme_snapshot('{"schemaVersion":1,"snapshotId":"x","name":"x","family":"custom","source":"custom","sourceOrganisation":null,"sourceVersion":null,"templateId":null,"modified":false,"machineVocabulary":["A"],"areas":[{"areaNumber":1,"presentations":[]}]}') then raise exception 'malformed accepted';end if;if public.is_complete_score_sheet_programme_snapshot((select p from pp where n='bad_single')) then raise exception 'incomplete single accepted';end if;if public.is_complete_score_sheet_programme_snapshot((select p from pp where n='bad_pair')) then raise exception 'incomplete pair accepted';end if;end$$;
insert into auth.users(id,email)values('00000000-0000-0000-0000-000000000274','i274-owner@example.test'),('00000000-0000-0000-0000-000000000275','i274-other@example.test');insert into public.user_access_profiles(user_id,email,access_status,system_role,account_type,approved_at)values('00000000-0000-0000-0000-000000000274','i274-owner@example.test','approved','user','personal',now()),('00000000-0000-0000-0000-000000000275','i274-other@example.test','approved','user','personal',now());set local role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000274',true);
insert into public.training_score_sheets(id,owner_user_id,title,session_date,discipline,session_type,number_of_posts,targets_per_post,total_targets,programme_snapshot)select'10000000-0000-0000-0000-000000000274',auth.uid(),'P',current_date,'Sporttrap','competition',1,1,1,p from pp where n='valid';insert into public.training_score_sheet_shooters(id,score_sheet_id,shooter_name)values('20000000-0000-0000-0000-000000000274','10000000-0000-0000-0000-000000000274','S');insert into public.training_score_sheet_target_results(score_sheet_id,shooter_id,post_number,target_number,result)values('10000000-0000-0000-0000-000000000274','20000000-0000-0000-0000-000000000274',1,1,'hit');
do $$declare rev timestamptz;begin update public.training_score_sheets set programme_snapshot=(select p from pp where n='valid')where id='10000000-0000-0000-0000-000000000274';if not found then raise exception'owner update denied';end if;select updated_at into rev from public.training_score_sheets where id='10000000-0000-0000-0000-000000000274';perform public.finalize_competition_score_sheet('10000000-0000-0000-0000-000000000274',rev,false);begin update public.training_score_sheets set programme_snapshot=(select p from pp where n='legacy')where id='10000000-0000-0000-0000-000000000274';raise exception'finalized mutation';exception when object_not_in_prerequisite_state then null;end;select updated_at into rev from public.training_score_sheets where id='10000000-0000-0000-0000-000000000274';perform public.reopen_competition_score_sheet('10000000-0000-0000-0000-000000000274',rev);update public.training_score_sheets set programme_snapshot=(select p from pp where n='bad_pair')where id='10000000-0000-0000-0000-000000000274';select updated_at into rev from public.training_score_sheets where id='10000000-0000-0000-0000-000000000274';begin perform public.finalize_competition_score_sheet('10000000-0000-0000-0000-000000000274',rev,false);raise exception'incomplete finalized';exception when invalid_parameter_value then null;end;end$$;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000275',true);do $$begin if exists(select 1 from public.training_score_sheets where id='10000000-0000-0000-0000-000000000274')then raise exception'cross read';end if;update public.training_score_sheets set programme_snapshot=null where id='10000000-0000-0000-0000-000000000274';if found then raise exception'cross mutation';end if;end$$;reset role;rollback;
